<?php
require_once __DIR__ . '/includes/auth.php'; require_login();
$userId=(int)$_SESSION['user_id']; $type=$_GET['type']??''; $year=(int)($_GET['year']??0); $month=(int)($_GET['month']??0); $search=trim($_GET['search']??''); $sql='SELECT * FROM transactions WHERE user_id=:user_id'; $params=['user_id'=>$userId]; if(in_array($type,['Income','Expense'],true)){$sql.=' AND type=:type';$params['type']=$type;} if($year>1900){$sql.=' AND YEAR(transaction_date)=:year';$params['year']=$year;} if($month>=1&&$month<=12){$sql.=' AND MONTH(transaction_date)=:month';$params['month']=$month;} if($search!==''){$sql.=' AND note LIKE :search';$params['search']='%'.$search.'%';} $sql.=' ORDER BY transaction_date DESC,id DESC';$statement=$pdo->prepare($sql);$statement->execute($params);$transactions=$statement->fetchAll();$pageTitle='Transactions';require __DIR__.'/includes/header.php';
?>
<div class="page-title"><div><span class="eyebrow">YOUR MONEY MOVEMENT</span><h1>Transactions</h1></div><a class="btn btn-primary" href="dashboard.php"><i class="fa-solid fa-plus me-1"></i> Add transaction</a></div><section class="panel"><form class="filter-grid" method="get"><div><label>Type</label><select class="form-select" name="type"><option value="">All types</option><option value="Income" <?= $type==='Income'?'selected':'' ?>>Income</option><option value="Expense" <?= $type==='Expense'?'selected':'' ?>>Expense</option></select></div><div><label>Year</label><input class="form-control" type="number" name="year" value="<?= $year?:'' ?>" placeholder="2026"></div><div><label>Month</label><input class="form-control" type="number" min="1" max="12" name="month" value="<?= $month?:'' ?>" placeholder="1-12"></div><div><label>Search note</label><input class="form-control" name="search" value="<?= e($search) ?>" placeholder="Search..."></div><button class="btn btn-primary"><i class="fa-solid fa-filter me-1"></i> Search</button></form></section><section class="panel mt-4"><div class="table-wrap"><table class="table"><thead><tr><th>ID</th><th>Date</th><th>Type</th><th>Amount</th><th>Note</th><th>Actions</th></tr></thead><tbody><?php if(!$transactions): ?><tr><td colspan="6" class="empty-state">No matching transactions.</td></tr><?php else: foreach($transactions as $transaction): ?><tr><td>#<?= (int)$transaction['id'] ?></td><td><?= pretty_date($transaction['transaction_date']) ?></td><td><span class="badge rounded-pill <?= $transaction['type']==='Income'?'badge-income':'badge-expense' ?>"><?= e($transaction['type']) ?></span></td><td class="fw-semibold <?= $transaction['type']==='Income'?'text-success':'text-danger' ?>"><?= $transaction['type']==='Expense'?'- ':'' ?><?= money($transaction['amount']) ?></td><td><?= e($transaction['note']?:'—') ?></td><td><a class="action-link" href="edit_transaction.php?id=<?= (int)$transaction['id'] ?>">Edit</a><a class="action-link delete" data-confirm="Are you sure you want to delete this transaction?" href="delete_transaction.php?id=<?= (int)$transaction['id'] ?>&token=<?= e(csrf_token()) ?>">Delete</a></td></tr><?php endforeach; endif; ?></tbody></table></div></section>
<?php require __DIR__.'/includes/footer.php'; ?>
